export const PRESETS: Record<string, PetProfile> = {
  lover: LOVER,
  pet: PET,
  friend: FRIEND,
  sister: SISTER,
};

export function getPreset(name: string | undefined): PetProfile {
  if (name && Object.prototype.hasOwnProperty.call(PRESETS, name)) {
    return PRESETS[name]!;
  }
  return LOVER; // sensible default given the project's current trajectory
}
